(()=>{'use strict';
const KEY='substop.subscriptions.v1'; const $=id=>document.getElementById(id);const now=()=>{const d=new Date();d.setHours(12,0,0,0);return d};const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const parseDate=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)};const fmt=n=>new Intl.NumberFormat('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);const money=n=>fmt(n)+' zł';const longDate=d=>new Intl.DateTimeFormat('pl-PL',{day:'numeric',month:'long',year:'numeric'}).format(d);const monthName=d=>new Intl.DateTimeFormat('pl-PL',{month:'short'}).format(d).replace('.','');const monthly=s=>s.amount*(s.cycle==='yearly'?1/12:s.cycle==='weekly'?52/12:1);const periodic={monthly:'mies.',yearly:'rok',weekly:'tydz.'};const icons={'Rozrywka':['▶','#fff0f0','#ef596b'],'Muzyka':['♫','#e7fff0','#2cba7a'],'Praca':['⌘','#eaf1ff','#6d8ff0'],'Zdrowie':['♥','#fff0df','#ef9b4d'],'Inne':['✦','#f1ebff','#9168e6']};
function addMonths(d,n,anchor){const y=d.getFullYear(),m=d.getMonth()+n;const target=new Date(y,m,1,12);const last=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(anchor,last));return target}function nextDate(s,from=now()){let d=parseDate(s.date);if(isNaN(d))return from;let count=0;if(s.cycle==='weekly'){if(d<from){count=Math.ceil((from-d)/86400000/7);d.setDate(d.getDate()+7*count)}return d}const stride=s.cycle==='yearly'?12:1;const anchor=d.getDate();while(d<from&&count++<1000)d=addMonths(parseDate(s.date),stride*count,anchor);return d}function futureOccurrences(s,start,end){const out=[];let d=nextDate(s,start),i=0;while(d<=end&&i++<400){out.push(new Date(d));if(s.cycle==='weekly')d=new Date(d.getFullYear(),d.getMonth(),d.getDate()+7,12);else d=addMonths(parseDate(s.date),(s.cycle==='yearly'?12:1)*i,parseDate(s.date).getDate())}return out}
function valid(s){return s&&typeof s.name==='string'&&s.name.trim().length>0&&s.name.length<=60&&Number.isFinite(s.amount)&&s.amount>0&&s.amount<1e9&&['weekly','monthly','yearly'].includes(s.cycle)&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&dateKey(parseDate(s.date))===s.date&&['active','paused'].includes(s.status)&&Object.keys(icons).includes(s.category)}
let subs=[];try{const data=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(data))subs=data.filter(valid)}catch(e){}let filter='all',editing=null;const saveData=()=>{try{localStorage.setItem(KEY,JSON.stringify(subs));window.dispatchEvent(new Event('substop:changed'));return true}catch(e){toast('Brak miejsca na zapis danych');return false}};
function el(tag,cls,text){const x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x}function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2500)}function empty(container,title,sub){const x=el('div','empty');x.append(el('b','',title),el('span','',sub));container.append(x)}
function render(){const active=subs.filter(s=>s.status==='active'),total=active.reduce((a,s)=>a+monthly(s),0);$('monthly').innerHTML=fmt(total)+' <small>zł</small>';$('yearly').textContent=money(total*12);$('active-count').textContent=active.length+' '+(active.length===1?'subskrypcja':'subskrypcji');$('list-count').textContent='('+subs.length+')';$('stats-month').textContent=money(total);$('stats-year').textContent=money(total*12);$('stats-active').textContent=String(active.length);$('stats-biggest').textContent=active.length?[...active].sort((a,b)=>monthly(b)-monthly(a))[0].name:'—';
const next=active.map(s=>({s,d:nextDate(s)})).sort((a,b)=>a.d-b.d)[0];const nearest=$('next-payment');nearest.replaceChildren();if(next){const row=el('div','upcoming'),date=el('div','datebox');date.append(el('b','',next.d.getDate()),el('span','',monthName(next.d)));const info=el('div','upcoming-info');info.append(el('b','',next.s.name),el('p','',next.d.toDateString()===now().toDateString()?'Dzisiaj':longDate(next.d)));row.append(date,info,el('div','upcoming-price',money(next.s.amount)));nearest.append(row)}else empty(nearest,'Spokojnie, bez płatności','Dodaj aktywną subskrypcję, aby zobaczyć termin.');
const list=$('subscriptions');list.replaceChildren();const visible=subs.filter(s=>filter==='all'||s.status===filter).sort((a,b)=>nextDate(a)-nextDate(b));if(!visible.length)empty(list,'Tu jeszcze pusto','Kliknij +, aby dodać pierwszą subskrypcję.');visible.forEach(s=>{const row=el('div','sub'),style=icons[s.category],logo=el('div','logo',style[0]);logo.style.background=style[1];logo.style.color=style[2];const info=el('div','sub-info');info.append(el('div','sub-name',s.name),el('div','sub-meta',s.status==='paused'?'Nieaktywna':('Następna: '+new Intl.DateTimeFormat('pl-PL',{day:'numeric',month:'short'}).format(nextDate(s)))));const price=el('div','sub-price');price.append(el('b','',money(s.amount)),el('div','', '/ '+periodic[s.cycle]));const btn=el('button','sub-menu','⋮');btn.type='button';btn.setAttribute('aria-label','Edytuj lub usuń '+s.name);btn.onclick=e=>{e.preventDefault();e.stopPropagation();openSheet(s.id)};row.append(logo,info,price,btn);row.onclick=e=>{if(!e.target.closest('button'))openSheet(s.id)};list.append(row)});
const payments=$('payments-list');payments.replaceChildren();if(!active.length)empty(payments,'Brak terminów','Dodaj aktywną subskrypcję.');else{const start=now(),end=new Date(start.getFullYear(),start.getMonth()+12,start.getDate(),12);const items=[];active.forEach(s=>futureOccurrences(s,start,end).forEach(d=>items.push({s,d})));items.sort((a,b)=>a.d-b.d);items.forEach(({s,d})=>{const row=el('div','month-row');const left=el('div');left.append(el('b','',s.name),el('div','hint',longDate(d)));row.append(left,el('b','',money(s.amount)));payments.append(row)})}}
function openSheet(id=null){const s=id===null?null:subs.find(x=>x.id===id);if(id!==null&&!s){toast('Nie znaleziono subskrypcji — odśwież listę');render();return}editing=s?.id??null;$('sheet-title').textContent=s?'Edytuj subskrypcję ✏️':'Nowa subskrypcja ✨';$('save').textContent=s?'Zapisz zmiany':'Dodaj subskrypcję';$('delete').hidden=!s;$('name').value=s?.name||'';$('amount').value=s?.amount||'';$('cycle').value=s?.cycle||'monthly';$('date').value=s?.date||dateKey(now());$('category').value=s?.category||'Rozrywka';$('status').value=s?.status||'active';$('modal').classList.add('show');setTimeout(()=>$('name').focus(),40)}function closeSheet(){$('modal').classList.remove('show');editing=null}
$('form').onsubmit=e=>{e.preventDefault();const s={id:editing||globalThis.crypto?.randomUUID?.()||String(Date.now()),name:$('name').value.trim(),amount:Number($('amount').value),cycle:$('cycle').value,date:$('date').value,category:$('category').value,status:$('status').value};if(!valid(s)){toast('Sprawdź wprowadzone dane');return}if(editing){const i=subs.findIndex(x=>x.id===editing);if(i<0)return;subs[i]=s}else subs.push(s);if(!saveData())return;closeSheet();render();toast(editing?'Zapisano zmiany':'Dodano subskrypcję')};$('delete').onclick=()=>{if(!editing)return;const s=subs.find(x=>x.id===editing);if(!s||!confirm('Usunąć subskrypcję '+s.name+'?'))return;subs=subs.filter(x=>x.id!==editing);saveData();closeSheet();render();toast('Usunięto subskrypcję')};$('close').onclick=closeSheet;$('modal').onclick=e=>{if(e.target===$('modal'))closeSheet()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet()});$('fab').onclick=()=>openSheet();$('quick-add').onclick=()=>openSheet();
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});function navigate(page){render();document.querySelectorAll('.screen').forEach(x=>x.classList.toggle('active',x.id===page));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.nav===page));window.dispatchEvent(new CustomEvent('substop:navigate',{detail:{page}}));window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('avatar').onclick=()=>navigate('settings');$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,subscriptions:subs},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='substop-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import-btn').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.subscriptions)||!data.subscriptions.every(valid))throw Error('bad');if(!confirm('Zastąpić bieżące subskrypcje danymi z kopii?'))return;subs=data.subscriptions;saveData();render();toast('Przywrócono dane')}catch(e){toast('Nieprawidłowy plik kopii')}finally{$('import-file').value=''}};
render();})();
